INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind funktionale Anforderungen dasselbe wie nicht-funktionale Anforderungen?', 2, '[{"text": "Nein", "correct": true, "because": "Funktion vs. Qualität"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Kategorien"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Hauptziel verfolgen funktionale Anforderungen?', 3, '[{"text": "Spezifische Systemfunktionen definieren", "correct": true, "because": "Was das System tun soll"}, {"text": "Leistung optimieren", "correct": false, "because": "Nicht-funktional"}, {"text": "Netzwerksicherheit erhöhen", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Beispiele gehören zu funktionalen Anforderungen?', 5, '[{"text": "Benutzeranmeldung", "correct": true, "because": "Spezifische Funktion"}, {"text": "Datenexport", "correct": true, "because": "Konkretes Verhalten"}, {"text": "Systemgeschwindigkeit", "correct": false, "because": "Nicht-funktional"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Funktionale Anforderungen beschreiben „was“ ein System tut. b) Sie definieren die Hardware.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Hardware nicht-funktional"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei funktionalen Anforderungen?', 4, '[{"text": "Systemverhalten", "correct": false, "because": "Kernmerkmal"}, {"text": "Benutzeranforderungen", "correct": false, "because": "Grundlage"}, {"text": "Papiergröße", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob funktionale Anforderungen messbar sein müssen?', 2, '[{"text": "Ja", "correct": true, "because": "Überprüfbar"}, {"text": "Nein", "correct": false, "because": "Testbarkeit nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Wo werden funktionale Anforderungen typischerweise dokumentiert?', 3, '[{"text": "Pflichtenheft", "correct": true, "because": "Entwicklungsgrundlage"}, {"text": "Netzwerkplan", "correct": false, "because": "Kein Bezug"}, {"text": "Papierhandbuch", "correct": false, "because": "Nicht spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten funktionale Anforderungen?', 5, '[{"text": "Klare Funktionsdefinition", "correct": true, "because": "Verständnis"}, {"text": "Testbarkeit", "correct": true, "because": "Überprüfung"}, {"text": "Papierersparnis", "correct": false, "because": "Kein Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Funktionale Anforderungen spezifizieren Systemfunktionen. b) Sie betreffen nur Hardware. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Softwarefokus"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für funktionale Anforderungen?', 4, '[{"text": "Benutzeranforderungen", "correct": false, "because": "Grundlage"}, {"text": "Systembeschreibung", "correct": false, "because": "Funktion definieren"}, {"text": "Farbcodierung", "correct": true, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind funktionale Anforderungen optional?', 2, '[{"text": "Nein", "correct": true, "because": "Pflicht für Entwicklung"}, {"text": "Ja", "correct": false, "because": "Kern der Spezifikation"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Dokumente enthalten funktionale Anforderungen?', 4, '[{"text": "Lastenheft", "correct": true, "because": "Kundenwünsche"}, {"text": "Pflichtenheft", "correct": true, "because": "Entwicklungsplan"}, {"text": "Netzwerkdiagramm", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass funktionale Anforderungen die Leistung definieren. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Nicht-funktional"}, {"text": "Ja", "correct": false, "because": "Funktion, nicht Leistung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei funktionalen Anforderungen?', 3, '[{"text": "Klarheit", "correct": true, "because": "Verständlichkeit"}, {"text": "Papierformate", "correct": false, "because": "Irrelevant"}, {"text": "Schnelligkeit", "correct": false, "because": "Qualität zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Funktionale Anforderungen sind spezifisch. b) Sie betreffen nur Sicherheit.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Sicherheit nicht-funktional"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte gehören zu funktionalen Anforderungen?', 5, '[{"text": "Benutzeraktionen", "correct": true, "because": "Funktionen"}, {"text": "Datenverarbeitung", "correct": true, "because": "Verhalten"}, {"text": "Systemgeschwindigkeit", "correct": false, "because": "Nicht-funktional"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei funktionalen Anforderungen unwichtig?', 3, '[{"text": "Funktionsbeschreibung", "correct": false, "because": "Kernmerkmal"}, {"text": "Testbarkeit", "correct": false, "because": "Überprüfung"}, {"text": "Schriftart", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind funktionale Anforderungen für die Entwicklung essenziell?', 3, '[{"text": "Ja", "correct": true, "because": "Grundlage"}, {"text": "Nein", "correct": false, "because": "Unverzichtbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob funktionale Anforderungen die Benutzeroberfläche betreffen?', 2, '[{"text": "Ja", "correct": true, "because": "UI-Funktionen"}, {"text": "Nein", "correct": false, "because": "Teilweise enthalten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist für funktionale Anforderungen zentral?', 4, '[{"text": "Systemverhalten", "correct": true, "because": "Kernprinzip"}, {"text": "Papierdokumentation", "correct": false, "because": "Sekundär"}, {"text": "Systemleistung", "correct": false, "because": "Nicht-funktional"}]');
